import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"家人","description":"周易集解 - 家人","frontmatter":{"title":"家人","description":"周易集解 - 家人"},"headers":[],"relativePath":"classics/jijie/037.md","filePath":"classics/jijie/037.md"}'),l={name:"classics/jijie/037.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="家人" tabindex="-1">家人 <a class="header-anchor" href="#家人" aria-label="Permalink to “家人”">​</a></h1><h2 id="家人-1" tabindex="-1">家人 <a class="header-anchor" href="#家人-1" aria-label="Permalink to “家人”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>家人，利女貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：傷於外者必反於家，故受之以家人。</p><p>韓康伯曰：傷於外者，必反諸內也。</p><p>虞翻曰：遯初之四也。女謂離巽。二四得正。故利女貞也。</p><p>馬融曰：家人以女為奧主。長女中女，各得其正，故特曰利女貞矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：家人，女正位乎內，男正位乎外。男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父，子子，兄兄，弟弟，夫夫，婦婦，而家道正。正家而天下定矣。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>王弼曰：謂二五也。家人之義，以內為本者也。故先說女矣。</p><p>虞翻曰：遯乾為天，三動坤為地。男得天，正於五；女得地，正於二。故天地之大義也。</p><p>荀爽曰：離巽之中有乾坤，故曰父母之謂也。</p><p>王肅曰：凡男女所以能各得其正者，由家人有嚴君也。家人有嚴君，故父子夫婦各得其正。家家鹹正，而天下之治大定矣。</p><p>案：二五相應，為卦之主。五陽在外，二陰在內，父母之謂也。</p><p>虞翻曰：遯乾為父，艮為子，三五位正，故｢父父，子子｣。三動時，震為兄，艮為弟，初位正，故｢兄兄、弟弟｣。</p><p>虞翻曰：三動時，震為夫，巽四為婦，初四位正，故｢夫夫，婦婦｣也。</p><p>荀爽曰：父謂五，子謂四，兄謂三，弟謂初，夫謂五，婦謂二也。各得其正，故｢天下定矣｣。</p><p>陸績曰：聖人教先從家始，家正而天下化之，脩己以安百姓者也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：風自火出，家人。君子以言有物而行有恆。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>馬融曰：木生火。火以木為家，故曰家人。火生於木，得風而盛，猶夫婦之道，相須而成。</p><p>荀爽曰：風火相與，必附於物。物大火大，物小火小。君子之言，必因其位。位大言大，位小言小。不在其位，不謀其政，故言有物也。大暑爍金，火不增其烈；大寒凝冰，火不損其熱，故曰行有恆矣。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，閑有家，悔亡。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：閑有家，志未變也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：初在潛位，未乾國政，閑習家事而已。未得治官，故悔。居家理治，可移於官，守之以正，故悔亡。而未變從國之事，故曰志未變也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，無攸遂，在中饋，貞吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>荀爽曰：六二處和得正。得正有應，有應有實，陰道之至美者也。坤道順從，故無所得遂。供餚中饋，酒食是議，故曰中饋。居中守正，永貞其志則吉，故曰貞吉也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六二之吉，順以巽也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：謂二居貞，巽順於五，則吉矣。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，家人嗃嗃，悔厲吉。婦子嘻嘻，終吝。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>王弼曰：以陽居陽，剛嚴者也。處下體之極，為一家之長，行與其慢也，寧過乎恭；家與其瀆也，寧過乎嚴。是以家雖嗃嗃，悔厲猶得吉也。婦子嘻嘻，失家節也。</p><p>侯果曰：嗃嗃，嚴也。嘻嘻，笑也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：家人嗃嗃，未失也。婦子嘻嘻，失家節也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：別體異家，陰陽相據，喜樂過節也。別體異家，謂三五也。陰陽相據，三五各相據陰，故言婦子也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，富家大吉。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：富家大吉，順在位也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：三變體艮，艮為篤實。坤為大業。得位應初，順五乘三，比據三陽，故曰｢富家大吉，順在位也｣，謂順於五矣。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，王假有家，勿恤，吉。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>陸績曰：假，大也。五得尊位，據四應二，以天下為家，故曰｢王大有家｣。天下正之，故無所憂則吉。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：王假有家，交相愛也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：乾為愛也，二稱家。三動成震。五得交二，初得交四，故交相愛。震為交也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，有孚威如，終吉。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：謂三已變，與上易位，成坎。坎為孚，故有孚。乾為威如，自上之坤，故威如。易則得位，故終吉也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：威如之吉，反身之謂也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂三動，坤為身。上之三，成既濟定，故｢反身之謂｣。此家道正，正家而天下定矣。</p>',72)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
